import os
import tomllib
from collections.abc import Mapping
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str):
        self.key = key
        self.expected = expected
        super().__init__(f"Invalid config: {key} = {expected}")


def _coerce(value: str, target: type) -> Any:
    if target is str:
        return value
    if target is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(value, "bool")
    if target is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(value, "int")
    if target is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(value, "float")
    raise ConfigError(value, str(target))


def _join_key(path: list[str], prefix: str) -> str:
    joined = "__".join(path)
    return f"{prefix}__{joined.upper()}"


def load_cfg(
    defaults: dict,
    toml_path: str | None = None,
    prefix: str = "APP",
    env: Mapping[str, str] | None = None,
) -> dict:
    cfg = dict(defaults)
    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                toml = tomllib.load(f)
            cfg = cfg | toml
        except FileNotFoundError:
            pass
    merged = cfg
    if env is None:
        env = os.environ
    for key, val in env.items():
        if not key.startswith(prefix + "__"):
            continue
        path = [k for k in key[len(prefix) + 2:].split("__")]
        if path[0] not in merged:
            raise ConfigError(key, "unknown")
        target = type(merged[path[0]])
        if isinstance(target, dict):
            raise ConfigError(key, "nested")
        try:
            merged[path[0]] = _coerce(val, target)
        except ConfigError as e:
            raise ConfigError(e.key, e.expected)
