import os
import tempfile
from pathlib import Path

import envcfg


def test_defaults_only():
    cfg = envcfg.load_cfg({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"a = 10\nc = 3")
        toml_path = f.name
    try:
        cfg = envcfg.load_cfg(defaults, toml_path)
    finally:
        os.unlink(toml_path)
    assert cfg == {"a": 10, "b": 2, "c": 3}


def test_env_overrides_toml_and_defaults():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b"a = 10\nc = 3")
        toml_path = f.name
    try:
        cfg = envcfg.load_cfg(defaults, toml_path, prefix="APP", env={"APP__A": "100", "APP__C": "4"})
    finally:
        os.unlink(toml_path)
    assert cfg == {"a": 100, "b": 2, "c": 4}


